def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if r is not None and math.isfinite(r) and r > 0 and x > 0:
            total += x * r * r * r
            weight += x
    if weight <= 0:
        return 0.0
    return float(4.0 * math.pi * total / (3.0 * weight * v))

def feature(s):
    sites = s.get('sites', ())
    occ = [max(0.0, float(t.get('occupancy', 1.0))) for t in sites]
    near = [math.inf] * len(sites)
    for b in s.get('neighbors', ()):
        i = b['i']
        d = b['distance_A']
        if occ[b['j']] > 0 and d > 1e-8 and d < near[i]:
            near[i] = d
    total = 0.0
    weight = 0.0
    for i in range(len(sites)):
        if math.isfinite(near[i]) and occ[i] > 0:
            total += occ[i] * near[i]
            weight += occ[i]
    return float(total / weight) if weight > 0 else 0.0

