def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    occ = [max(0.0, float(t.get('occupancy', 1.0))) for t in sites]
    near = [math.inf] * n
    neighbors = s.get('neighbors', ())
    for b in neighbors:
        i = b['i']
        d = b['distance_A']
        if occ[b['j']] > 0 and d > 1e-8 and d < near[i]:
            near[i] = d
    coord = [0.0] * n
    for b in neighbors:
        i = b['i']
        d = b['distance_A']
        if d > 1e-8 and d <= 1.25 * near[i]:
            coord[i] += occ[b['j']]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    mean = sum(occ[i] * coord[i] for i in range(n)) / weight
    variance = sum(occ[i] * (coord[i] - mean) ** 2 for i in range(n)) / weight
    return float(math.sqrt(max(0.0, variance)))

def feature(s):
    sites = s.get('sites', ())
    occ = [max(0.0, float(t.get('occupancy', 1.0))) for t in sites]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    props = s.get('element_properties', {})
    en = [props.get(t['element'], {}).get('eneg') for t in sites]
    near = [math.inf] * len(sites)
    neighbors = s.get('neighbors', ())
    for b in neighbors:
        i = b['i']
        d = b['distance_A']
        if occ[b['j']] > 0 and d > 1e-8 and d < near[i]:
            near[i] = d
    total = 0.0
    for b in neighbors:
        i = b['i']
        j = b['j']
        d = b['distance_A']
        a = en[i]
        if d > 1e-8 and d <= 1.25 * near[i] and sites[i]['element'] == sites[j]['element']:
            if a is not None and math.isfinite(a) and a >= 2.5:
                total += occ[i] * occ[j]
    return float(total / (2.0 * weight))

